import React from "react";
import type { StickerProps } from "../../types";
import { AnimatedSticker } from "../../components/AnimatedSticker";

// Exact reference pixels embedded as a lossless PNG — same technique as CatbeatsSticker.
const IMAGE = "data:image/png;base64,";

/**
 * Spooky Reaper Sticker — reproduced from the original Dribbble reference artwork.
 * Text, if any, is baked into the artwork and is not configurable.
 */
export const SpookyReaperSticker: React.FC<StickerProps> = (props) => (
  <AnimatedSticker
    {...props}
    label="Spooky Reaper Sticker"
    viewBox="0 0 279 320"
    motion="sway"
    duration={4.4}
    origin="140px 320px"
  >
    <image href={IMAGE} x={0} y={0} width={279} height={320} />
  </AnimatedSticker>
);

export default SpookyReaperSticker;
